css:
.p32-wrap { max-width: 56rem; margin-inline: auto; display: grid; gap: var(--s-4); }
.p32-top { display: grid; gap: var(--s-2); }
.p32-top:empty { display: none; }
.p32-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2); }
.p32-groups { display: grid; gap: var(--s-4); }
.p32-groups .group { gap: var(--s-2); }
.p32-list .rec__actions { flex-wrap: wrap; justify-content: flex-end; }
.p32-list .rec__actions .link-btn { margin-inline-start: var(--s-2); }
.p32-list .rec__title { display: inline-flex; align-items: center; min-height: var(--hit); }
.p32-ok { display: inline-grid; place-items: center; min-width: var(--hit); min-height: var(--hit); }
.p32-rtipw { grid-column: 1 / -1; }
.p32-rtip { display: flex; justify-content: flex-end; }
.p32-nolinks { padding: var(--s-1) 0; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p32-wrap.is-scrolled .p32-bar, .p32-wrap.is-scrolled .p32-above { display: none; } }
.p32-dis .link-btn[aria-disabled="true"] { color: var(--c-disabled-text); text-decoration: none; cursor: not-allowed; }
.p32-err { --frame-w: var(--w2); }
.p32-errbox { display: grid; gap: var(--s-3); justify-items: start; width: min(100%, 32rem); }
.p32-errbox .banner { width: 100%; }
.p32-center { min-height: calc(100cqh - 2 * var(--s-3)); display: grid; align-content: center; justify-items: center; gap: var(--s-3); text-align: center; padding: var(--s-5) var(--s-3); }
.p32-center p { max-width: var(--measure); }
.p32-load { justify-content: center; }
.p32-msg { color: var(--ink); max-width: var(--measure); }
.p32-nocards { display: grid; justify-items: start; gap: var(--s-3); padding: var(--s-4) 0; }
.p32-tiprow { display: flex; }

.p32-dlg .dialog__body { gap: var(--s-3); }
.p32-form { display: grid; gap: var(--s-4); }
.p32-cards { display: grid; gap: 0; }
.p32-cards .check { min-height: var(--hit); }
.p32-cards .check input:disabled:checked + .check__box { background-color: var(--line); border-color: var(--line); }
.p32-cards .check__label { flex: 1; }
.p32-cards .p32-conn { margin-inline-start: auto; font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p32-cards .check { width: 100%; }
.p32-grp-head { display: flex; justify-content: space-between; align-items: baseline; gap: var(--s-2); font-size: var(--fs-small); line-height: var(--lh-small); font-weight: var(--fw-semibold); }
.p32-area .textarea, .textarea.p32-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; field-sizing: content; }
.p32-url { text-overflow: ellipsis; white-space: nowrap; }
.input.p32-ro, .textarea.p32-ro { border-color: var(--rule); color: var(--muted); background: var(--white); }
.input.p32-focus, .textarea.p32-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p32-dup { flex-wrap: wrap; }
.p32-dup .banner__text { flex: 1 1 10rem; }
.p32-errwrap { padding: 0 var(--s-4); }
.p32-tipslot { display: flex; justify-content: flex-end; padding: var(--s-2) var(--s-4) 0; }
.p32-hint { color: var(--muted); font-size: var(--fs-cap); line-height: var(--lh-cap); }
.p32-note { font-size: var(--fs-small); line-height: var(--lh-small); }
.p32-foot { }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } .tabwrap > .tab { padding-inline: var(--s-1) 1.75rem; font-size: var(--fs-cap); } }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.dialog__head { align-items: center; }
.field__hint { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p32-urltext { margin: 0; overflow-wrap: anywhere; word-break: break-all; font-size: var(--fs-small); line-height: var(--lh-small); user-select: text; }
